[ApiDescriptionSettings(Tag = "Extend", Name = "CrmOrder", Order = 200)]
[Route("api/extend/[controller]")]
public class OrderService : IDynamicApiController, ITransient
{
    private readonly ISqlSugarRepository<OrderEntity> _repository;
    private readonly IUsersService _usersService;
    private readonly ICacheManager _cacheManager;
    private readonly IFileManager _fileManager;
    private readonly IUserManager _userManager; // 鐢ㄦ埛绠＄悊

    public OrderService(
        ISqlSugarRepository<OrderEntity> repository,
        IUserManager userManager,
        IUsersService usersService,
        ICacheManager cacheManager)
    {
        _repository = repository;
        _userManager = userManager;
        _usersService = usersService;
        _cacheManager = cacheManager;
    }

    #region GET

    /// <summary>
    /// 鍒楄〃.
    /// </summary>
    /// <param name="input">璇锋眰鍙傛暟</param>
    /// <returns></returns>
    [HttpGet("")]
    public async Task<dynamic> GetList([FromQuery] OrderListQuery input)
    {
        var queryWhere = LinqExpression.And<OrderListOutput>();
        var authorizeWhere = new List<IConditionalModel>();

        // 鍏抽敭瀛楋紙璁㈠崟缂栫爜銆佸鎴峰悕绉般€佷笟鍔′汉鍛橈級
        if (input.keyword.IsNotEmptyOrNull())
            queryWhere = queryWhere.And(m => m.orderCode.Contains(input.keyword) || m.customerName.Contains(input.keyword) || m.salesmanName.Contains(input.keyword));

        // 璧峰鏃ユ湡-缁撴潫鏃ユ湡
        if (input.endTime != null && input.startTime != null)
        {
            queryWhere = queryWhere.And(x => SqlFunc.Between(x.orderDate, input.startTime, input.endTime));
        }

        // 鏁版嵁鏉冮檺杩囨护
        var menu = await _repository.AsSugarClient().Queryable<ModuleEntity>().FirstAsync(x => x.EnCode == "extend.order");
        if (_userManager.User.IsAdministrator == 0)
            authorizeWhere = await _userManager.GetConditionAsync<OrderListOutput>(menu.Id, "F_ID", true, "a.");
        var pageList = await _repository.AsSugarClient().Queryable<OrderEntity, UserEntity, FlowTaskEntity>((a, b, c) => new JoinQueryInfos(JoinType.Left, a.CreatorUserId == b.Id, JoinType.Left, a.Id == c.Id))
            .Where((a, b) => a.DeleteMark == null).Where(authorizeWhere)
            .Select((a, b, c) => new OrderListOutput()
            {
                creatorUser = SqlFunc.MergeString(b.RealName, "/", b.Account),
                creatorUserId = a.CreatorUserId,
                currentState = c.Status,
                customerName = a.CustomerName,
                description = a.Description,
                id = a.Id,
                orderCode = a.OrderCode,
                orderDate = a.OrderDate,
                receivableMoney = a.ReceivableMoney,
                salesmanName = a.SalesmanName,
                creatorTime = a.CreatorTime,
                sortCode = a.SortCode,
                lastModifyTime = a.LastModifyTime,
                flowId = a.FlowId,
            }).MergeTable().Where(queryWhere)
        .OrderBy(a => a.sortCode)
        .OrderBy(a => a.creatorTime, OrderByType.Desc)
        .OrderByIF(!string.IsNullOrEmpty(input.keyword), t => t.lastModifyTime, OrderByType.Desc)
        .ToPagedListAsync(input.currentPage, input.pageSize);
        return PageResult<OrderListOutput>.SqlSugarPageResult(pageList);
    }

    /// <summary>
    /// 瀛愬垪琛紙璁㈠崟鏄庣粏锛?
    /// </summary>
    /// <param name="id">涓昏〃Id.</param>
    /// <returns></returns>
    [HttpGet("OrderEntry/{id}/Items")]
    public async Task<dynamic> GetEntryList(string id)
    {
        var data = await _repository.AsSugarClient().Queryable<OrderEntryEntity>().Where(x => x.OrderId == id).OrderBy(x => x.SortCode).ToListAsync();
        var output = data.Adapt<List<OrderItemsOutput>>();
        return new { list = output };
    }

    /// <summary>
    /// 瀛愬垪琛紙璁㈠崟鏀舵锛?
    /// </summary>
    /// <param name="id">涓昏〃Id.</param>
    /// <returns></returns>
    [HttpGet("{id}/CollectionPlan")]
    public async Task<dynamic> GetReceivableList(string id)
    {
        var data = await _repository.AsSugarClient().Queryable<OrderReceivableEntity>().Where(x => x.OrderId == id).OrderBy(o => o.SortCode).ToListAsync();
        var output = data.Adapt<List<OrderCollectionPlanOutput>>();
        return new { list = output };
    }

    /// <summary>
    /// 淇℃伅.
    /// </summary>
    /// <param name="id">涓婚敭鍊?</param>
    /// <returns></returns>
    [HttpGet("{id}")]
    public async Task<dynamic> GetInfo(string id)
    {
        if ("0".Equals(id)) return null;
        var data = (await _repository.GetFirstAsync(x => x.Id == id && x.DeleteMark == null)).Adapt<OrderInfoOutput>();
        if (data.IsNullOrEmpty()) return null;
        data.collectionPlanList = (await _repository.AsSugarClient().Queryable<OrderReceivableEntity>().Where(x => x.OrderId == id).ToListAsync()).Adapt<List<CollectionPlanModel>>();
        data.goodsList = (await _repository.AsSugarClient().Queryable<OrderEntryEntity>().Where(x => x.OrderId == id).ToListAsync()).Adapt<List<GoodsModel>>();
        data.creatorUserId = await _usersService.GetUserName(data.creatorUserId);
        data.lastModifyUserId = await _usersService.GetUserName(data.lastModifyUserId);
        return data;
    }

