    #region POST

    /// <summary>
    /// 淇濆瓨鏁版嵁.
    /// </summary>
    /// <param name="id">涓婚敭鍊?</param>
    /// <param name="input">璇锋眰鍙傛暟.</param>
    /// <returns></returns>
    [HttpPost("{id}")]
    public async Task Save(string id, [FromBody] OrderCrInput input)
    {
        var orderEntity = input.Adapt<OrderEntity>();
        orderEntity.Id = id;
        var orderEntryList = input.goodsList.Adapt<List<OrderEntryEntity>>();
        var orderReceivableList = input.collectionPlanList.Adapt<List<OrderReceivableEntity>>();
        if (orderEntryList.IsNotEmptyOrNull())
        {
            foreach (var itemEntity in orderEntryList)
            {
                itemEntity.Id = SnowflakeIdHelper.NextId();
                itemEntity.OrderId = orderEntity.Id;
                itemEntity.SortCode = orderEntryList.IndexOf(itemEntity);
            }
        }

        if (orderEntryList.IsNotEmptyOrNull())
        {
            foreach (var itemEntity in orderReceivableList)
            {
                itemEntity.Id = YitIdHelper.NextId().ToString();
                itemEntity.OrderId = orderEntity.Id;
                itemEntity.SortCode = orderReceivableList.IndexOf(itemEntity);
            }
        }

        if (_repository.IsAny(x => x.Id == orderEntity.Id))
        {
            await _repository.AsSugarClient().Deleteable<OrderEntryEntity>(x => x.OrderId == id).ExecuteCommandAsync();
            await _repository.AsSugarClient().Deleteable<OrderReceivableEntity>(x => x.OrderId == id).ExecuteCommandAsync();
            await _repository.AsSugarClient().Insertable(orderEntryList).ExecuteCommandAsync();
            await _repository.AsSugarClient().Insertable(orderReceivableList).ExecuteCommandAsync();
            await _repository.AsSugarClient().Updateable(orderEntity).IgnoreColumns(ignoreAllNullColumns: true).CallEntityMethod(m => m.LastModify()).ExecuteCommandAsync();
        }
        else
        {
            _cacheManager.Del(string.Format("{0}{1}_{2}", CommonConst.CACHEKEYBILLRULE, _userManager.TenantId, _userManager.UserId + "OrderNumber"));
            await _repository.AsSugarClient().Insertable(orderEntryList).ExecuteCommandAsync();
            await _repository.AsSugarClient().Insertable(orderReceivableList).ExecuteCommandAsync();
            await _repository.AsSugarClient().Insertable(orderEntity).CallEntityMethod(m => m.Create()).ExecuteCommandAsync();
        }
    }

    /// <summary>
    /// 鍒犻櫎.
    /// </summary>
    /// <param name="id">涓婚敭鍊?/param>
    /// <returns></returns>
    [HttpDelete("{id}")]
    public async Task Delete(string id)
    {
        var entity = await _repository.GetFirstAsync(x => x.Id == id && x.DeleteMark == null);
        if (entity != null)
        {
            await _repository.AsSugarClient().Deleteable<OrderEntryEntity>(x => x.OrderId == id).ExecuteCommandAsync();
            await _repository.AsSugarClient().Deleteable<OrderReceivableEntity>(x => x.OrderId == id).ExecuteCommandAsync();
            await _repository.AsSugarClient().Updateable(entity).CallEntityMethod(m => m.Delete()).UpdateColumns(it => new { it.DeleteMark, it.DeleteTime, it.DeleteUserId }).ExecuteCommandHasChangeAsync();
            var flowTaskEntity = await _repository.AsSugarClient().Queryable<FlowTaskEntity>().FirstAsync(x => x.Id == entity.Id);
            if (flowTaskEntity.IsNotEmptyOrNull())
            {
                await _repository.AsSugarClient().Updateable(flowTaskEntity).CallEntityMethod(m => m.Delete()).UpdateColumns(it => new { it.DeleteMark, it.DeleteTime, it.DeleteUserId }).ExecuteCommandHasChangeAsync();
            }
            foreach (var item in entity.FileJson.ToList<AnnexModel>())
            {
                if (item.IsNotEmptyOrNull())
                {
                    await _fileManager.DeleteFile(Path.Combine(FileVariable.SystemFilePath, item.FileName));
                }
            }
        }
    }
    #endregion

    #region PrivateMethod

    /// <summary>
    /// 鏍规嵁瀛楁杩囨护琛ㄧ殑鍐呭.
    /// </summary>
    /// <param name="data">琛ㄦ暟鎹?</param>
    /// <param name="condition">鏉′欢.</param>
    /// <returns></returns>
    private DataTable GetDataFilter(DataTable data, string condition)
    {
        if (data != null && data.Rows.Count > 0)
        {
            if (condition.Trim() == string.Empty)
            {
                return data;
            }
            else
            {
                DataTable newdt = new DataTable();
                newdt = data.Clone();
                DataRow[] dr = data?.Select(condition);
                for (int i = 0; i < dr.Length; i++)
                {
                    newdt.ImportRow((DataRow)dr[i]);
                }
                return newdt;
            }
        }
        else
        {
            return new DataTable();
        }
    }

    /// <summary>
    /// 鑾峰彇琛ㄩ噷鍓嶅嚑鏉℃暟鎹?
    /// </summary>
    /// <param name="data">琛ㄦ暟鎹?/param>
    /// <param name="top"></param>
    /// <returns></returns>
    private DataTable GetSelectTop(DataTable data, int top)
    {
        if (data.Rows.Count < top) return data;
        DataTable NewTable = data.Clone();
        DataRow[] rows = data.Select("1=1");
        for (int i = 0; i < top; i++)
        {
            NewTable.ImportRow((DataRow)rows[i]);
        }
        return NewTable;
    }
    #endregion
